def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    uncomputed = object()
    in_progress = object()

    has_cell = [False] * 2574
    cell_vals: list[object] = [uncomputed] * 2574
    cell_asts: list[object] = [None] * 2574
    entries: list[tuple[str, int]] = []

    def cell_index(name: str) -> int:
        return (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)

    def parse_formula(expr: str) -> tuple:
        tokens: list[tuple] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= expr[j] <= "9":
                    j += 1
                tokens.append(("NUM", int(expr[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and "A" <= expr[j] <= "Z":
                    j += 1
                if j < n and "0" <= expr[j] <= "9":
                    k = j + 1
                    while k < n and "0" <= expr[k] <= "9":
                        k += 1
                    idx = (int(expr[j:k]) - 1) * 26 + (ord(ch) - 65)
                    tokens.append(("CELL", idx))
                    i = k
                else:
                    tokens.append(("FUNC", expr[i:j]))
                    i = j
            elif ch == "<":
                if i + 1 < n and expr[i + 1] in ("=", ">"):
                    tokens.append(("OP", expr[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and expr[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1

        pos = 0
        n_tok = len(tokens)

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while pos < n_tok and tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while pos < n_tok and tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            neg = 0
            while pos < n_tok and tokens[pos][0] == "-":
                neg ^= 1
                pos += 1
            node = parse_atom()
            return ("NEG", node) if neg else node

        def parse_atom() -> tuple:
            nonlocal pos
            tok = tokens[pos]
            kind = tok[0]
            if kind == "NUM":
                pos += 1
                return ("LIT", tok[1])
            if kind == "CELL":
                pos += 1
                return ("CELL", tok[1])
            if kind == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            fn = tok[1]
            pos += 2
            if fn == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_e = parse_expr()
                pos += 1
                else_e = parse_expr()
                pos += 1
                return ("IF", op, left, right, then_e, else_e)
            args = []
            while True:
                if (
                    tokens[pos][0] == "CELL"
                    and pos + 1 < n_tok
                    and tokens[pos + 1][0] == ":"
                ):
                    r1, c1 = divmod(tokens[pos][1], 26)
                    r2, c2 = divmod(tokens[pos + 2][1], 26)
                    pos += 3
                    if r1 > r2:
                        r1, r2 = r2, r1
                    if c1 > c2:
                        c1, c2 = c2, c1
                    args.append(("RANGE", r1, c1, r2, c2))
                else:
                    args.append(parse_expr())
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return ("AGG", fn, args)

        return parse_expr()

    for name, content in cells.items():
        idx = cell_index(name)
        has_cell[idx] = True
        entries.append((name, idx))
        stripped = content.lstrip()
        if stripped.startswith("="):
            cell_asts[idx] = parse_formula(stripped[1:])
        else:
            cell_vals[idx] = int(stripped)

    for _, start_idx in entries:
        if cell_vals[start_idx] is not uncomputed:
            continue

        cell_vals[start_idx] = in_progress
        frames: list[tuple] = [("CELL_DONE", start_idx)]
        cur_expr = cell_asts[start_idx]
        has_val = False
        ret_val: int | str | None = None

        while frames:
            if not has_val:
                kind = cur_expr[0]
                if kind == "LIT":
                    ret_val = cur_expr[1]
                    has_val = True
                elif kind == "CELL":
                    cidx = cur_expr[1]
                    if not has_cell[cidx]:
                        ret_val = 0
                        has_val = True
                    else:
                        v = cell_vals[cidx]
                        if v is in_progress:
                            ret_val = "#CYCLE!"
                            has_val = True
                        elif v is not uncomputed:
                            ret_val = v
                            has_val = True
                        else:
                            cell_vals[cidx] = in_progress
                            frames.append(("CELL_DONE", cidx))
                            cur_expr = cell_asts[cidx]
                elif kind == "NEG":
                    frames.append(("NEG",))
                    cur_expr = cur_expr[1]
                elif kind == "BIN":
                    frames.append(("BIN_L", cur_expr[1], cur_expr[3]))
                    cur_expr = cur_expr[2]
                elif kind == "IF":
                    frames.append(("IF_L", cur_expr[1], cur_expr[3], cur_expr[4], cur_expr[5]))
                    cur_expr = cur_expr[2]
                else:
                    frames.append(("AGG", [cur_expr[1], cur_expr[2], 0, -1, -1, None]))
                    ret_val = None
                    has_val = True
                continue

            top = frames[-1]
            tkind = top[0]

            if tkind == "CELL_DONE":
                frames.pop()
                cell_vals[top[1]] = ret_val
            elif tkind == "NEG":
                frames.pop()
                if not isinstance(ret_val, str):
                    ret_val = -ret_val
            elif tkind == "BIN_L":
                frames.pop()
                if not isinstance(ret_val, str):
                    frames.append(("BIN_R", top[1], ret_val))
                    cur_expr = top[2]
                    has_val = False
            elif tkind == "BIN_R":
                frames.pop()
                if not isinstance(ret_val, str):
                    op = top[1]
                    lv = top[2]
                    rv = ret_val
                    if op == "+":
                        ret_val = lv + rv
                    elif op == "-":
                        ret_val = lv - rv
                    elif op == "*":
                        ret_val = lv * rv
                    elif rv == 0:
                        ret_val = "#DIV/0!"
                    else:
                        q = abs(lv) // abs(rv)
                        ret_val = -q if (lv < 0) ^ (rv < 0) else q
            elif tkind == "IF_L":
                frames.pop()
                if not isinstance(ret_val, str):
                    frames.append(("IF_R", top[1], ret_val, top[3], top[4]))
                    cur_expr = top[2]
                    has_val = False
            elif tkind == "IF_R":
                frames.pop()
                if not isinstance(ret_val, str):
                    op = top[1]
                    lv = top[2]
                    rv = ret_val
                    if op == "=":
                        cond = lv == rv
                    elif op == "<>":
                        cond = lv != rv
                    elif op == "<":
                        cond = lv < rv
                    elif op == "<=":
                        cond = lv <= rv
                    elif op == ">":
                        cond = lv > rv
                    else:
                        cond = lv >= rv
                    cur_expr = top[3] if cond else top[4]
                    has_val = False
            else:
                st = top[1]
                fn, args, arg_i, r, c, acc = st
                if ret_val is not None:
                    if isinstance(ret_val, str):
                        frames.pop()
                        continue
                    if fn == "SUM":
                        acc = ret_val if acc is None else acc + ret_val
                    elif fn == "MIN":
                        acc = ret_val if acc is None or ret_val < acc else acc
                    else:
                        acc = ret_val if acc is None or ret_val > acc else acc
                    st[5] = acc

                n_args = len(args)
                dispatched = False
                while arg_i < n_args:
                    arg = args[arg_i]
                    if arg[0] == "RANGE":
                        _, r1, c1, r2, c2 = arg
                        if r == -1:
                            r = r1
                            c = c1
                        while r <= r2:
                            base = r * 26
                            while c <= c2:
                                cidx = base + c
                                if has_cell[cidx]:
                                    v = cell_vals[cidx]
                                    if v is in_progress:
                                        frames.pop()
                                        ret_val = "#CYCLE!"
                                        has_val = True
                                        dispatched = True
                                        break
                                    if v is uncomputed:
                                        nc = c + 1
                                        nr = r
                                        if nc > c2:
                                            nc = c1
                                            nr = r + 1
                                        if nr > r2:
                                            st[2] = arg_i + 1
                                            st[3] = -1
                                            st[4] = -1
                                        else:
                                            st[2] = arg_i
                                            st[3] = nr
                                            st[4] = nc
                                        cell_vals[cidx] = in_progress
                                        frames.append(("CELL_DONE", cidx))
                                        cur_expr = cell_asts[cidx]
                                        has_val = False
                                        dispatched = True
                                        break
                                    if isinstance(v, str):
                                        frames.pop()
                                        ret_val = v
                                        has_val = True
                                        dispatched = True
                                        break
                                    if fn == "SUM":
                                        acc = v if acc is None else acc + v
                                    elif fn == "MIN":
                                        acc = v if acc is None or v < acc else acc
                                    else:
                                        acc = v if acc is None or v > acc else acc
                                    st[5] = acc
                                c += 1
                            if dispatched:
                                break
                            r += 1
                            c = c1
                        if dispatched:
                            break
                        arg_i += 1
                        r = -1
                        c = -1
                        st[2] = arg_i
                        st[3] = -1
                        st[4] = -1
                    else:
                        st[2] = arg_i + 1
                        st[3] = -1
                        st[4] = -1
                        cur_expr = arg
                        has_val = False
                        dispatched = True
                        break
                if not dispatched:
                    frames.pop()
                    ret_val = 0 if acc is None else acc
                    has_val = True

    return {name: cell_vals[idx] for name, idx in entries}
